// Same job as the original Normalize_Payload node: flatten the source records
// and convert tracked time from milliseconds to hours.
const results = [];
for (const item of $input.all()) {
  for (const task of item.json.tasks ?? []) {
    const trackedHours = (Number(task.time_spent_ms) || 0) / 3_600_000;
    results.push({
      json: {
        task_id: String(task.id),
        task_name: task.name,
        budget_hours: Number(task.budget_hours) || 0,
        tracked_hours: Math.round(trackedHours * 100) / 100,
      },
    });
  }
}
return results;

// The core of the original workflow. A task with no stored state starts as NEW.
// An alert is needed only when the state changed AND the new state is not HEALTHY,
// so a task that stays CRITICAL does not alert on every run.
const tasks = $('Normalize payload').all().map(i => i.json);
const previous = new Map(
  $input.all().filter(i => i.json.task_id).map(i => [i.json.task_id, i.json.current_state]),
);

return tasks.map(task => {
  const previousState = previous.get(task.task_id) ?? 'NEW';
  const percent = task.budget_hours > 0 ? (task.tracked_hours / task.budget_hours) * 100 : 0;

  let newState = 'HEALTHY';
  if (percent >= 100) newState = 'CRITICAL';
  else if (percent >= 80) newState = 'WARNING';

  return {
    json: {
      ...task,
      burn_percent: Math.round(percent * 10) / 10,
      previous_state: previousState,
      new_state: newState,
      requires_alert: newState !== previousState && newState !== 'HEALTHY',
    },
  };
});
